mapper.select:
SELECT /*selectMasterWmStStockSum*/ NVL(SUM(STCK.STC_SELLER_PRICE*STCK.AVAIL_QTY),0) FROM WMSSTCK STCK, ICOMCQDT CQDT, CMSCATLG CMS WHERE STCK.WAREHOUSE_CODE=#{st_warehouse_code} AND STCK.WAREHOUSE_CODE = CQDT.BUYER AND STCK.STDCATLG_ID = CQDT.BUYER_ITEM_NO AND STCK.AGENT = DECODE(CQDT.PROCESS_TYPE,'1','KRKORE0001','3',STCK.AGENT ) AND STCK.AVAIL_QTY <> 0 AND STCK.STDCATLG_ID = CMS.CMS_CATLG_ID
AND STCK.STDCATLG_ID LIKE '%'||#{st_stdcatlg_id} ||'%'
AND STCK.AGENT = #{st_agent_code}
AND STCK.PROCESS_TYPE IN ('1','3')
AND STCK.PROCESS_TYPE = #{st_process_type}
AND CMS.KEP_DEPT = #{st_dept}
AND CMS.STOCK_GROUP_TYPE = #{st_group_type}
AND CQDT.DESCRIPTION LIKE '%'||#{st_description}||'%'
AND CQDT.SPECIFICATION LIKE'%'||#{st_specification}||'%'
AND STCK.AVAIL_QTY > 0
AND STCK.AVAIL_QTY = 0
